-- Live Language Coach: starter content (8-statement anxiety questionnaire + six 10-question pre-tests).
-- Safe to run more than once: an activity is added only if no activity with the same title exists.
do $seed$ declare aid uuid; begin
  if not exists(select 1 from public.activities where title=$t$English language anxiety questionnaire$t$) then
    insert into public.activities(kind,purpose,title,skill,intro,passage,questions,status,sort) values('questionnaire','anxiety',$t$English language anxiety questionnaire$t$,null,$t$Choose the answer that best matches how you feel. There are no right or wrong answers.$t$,null,$j$[{"type": "likert", "q": "I feel nervous when I have to speak English in class."}, {"type": "likert", "q": "I worry about making mistakes when I use English."}, {"type": "likert", "q": "I feel confident when I answer in English.", "reverse": true}, {"type": "likert", "q": "I get anxious when I do not understand what the teacher says in English."}, {"type": "likert", "q": "I avoid speaking English when I can."}, {"type": "likert", "q": "I feel relaxed when I write in English.", "reverse": true}, {"type": "likert", "q": "I worry that other students will laugh at my English."}, {"type": "likert", "q": "I feel prepared for English tests.", "reverse": true}]$j$::jsonb,'published',1) returning id into aid;
    insert into public.activity_keys(activity_id,keys) values(aid,$j$[{}, {}, {}, {}, {}, {}, {}, {}]$j$::jsonb);
  end if;
  if not exists(select 1 from public.activities where title=$t$Listening pre-test$t$) then
    insert into public.activities(kind,purpose,title,skill,intro,passage,questions,status,sort) values('quiz','pretest',$t$Listening pre-test$t$,$t$Listening$t$,$t$Press Play audio, listen carefully, then answer.$t$,null,$j$[{"type": "mcq", "q": "When do the boats return?", "options": ["At five in the morning", "Before noon", "In the evening", "At midnight"], "say": "The boats leave the harbour at five in the morning and return before noon."}, {"type": "mcq", "q": "What should you do before you step into the boat?", "options": ["Wear a life jacket", "Remove your shoes", "Buy a ticket", "Call the captain"], "say": "Please wear your life jacket before you step into the boat."}, {"type": "mcq", "q": "Why did Meena stay at home?", "options": ["She was ill", "The beach was closed", "It rained heavily", "She had homework"], "say": "Meena wanted to go to the beach, but it started raining heavily, so she stayed at home."}, {"type": "tf", "q": "The fish market is open on Sundays.", "say": "The fish market is closed on Sundays, but it opens early on Monday."}, {"type": "mcq", "q": "Where is the library?", "options": ["Next to the lighthouse", "Behind the post office", "Opposite the post office", "Beside the bus stand"], "say": "Take the second left after the lighthouse. The library is opposite the post office."}, {"type": "mcq", "q": "How much is a ticket for a child?", "options": ["Forty rupees", "Fourteen rupees", "Fifty rupees", "Fifteen rupees"], "say": "The ferry ticket costs forty rupees for adults and fifteen rupees for children."}, {"type": "tf", "q": "The fishermen went out to sea.", "say": "Although the sea was rough, the fishermen decided to go out, because the forecast promised calm weather by noon."}, {"type": "mcq", "q": "When is the next bus?", "options": ["At nine o'clock", "At half past ten", "At half past nine", "At ten o'clock"], "say": "I'm afraid the nine o'clock bus has already left. The next one is at half past ten."}, {"type": "mcq", "q": "What does the speaker want?", "options": ["The listener to speak louder", "The listener to stop talking", "To go for a swim", "To hear the waves"], "say": "Could you speak a little louder, please? I can't hear you over the waves."}, {"type": "mcq", "q": "What happens at high tide?", "options": ["The boats stay in the harbour", "The rocks become dry", "The water covers the rocks", "The fishermen go home"], "say": "The tide comes in twice a day. At high tide, the water covers the rocks near the shore."}]$j$::jsonb,'published',10) returning id into aid;
    insert into public.activity_keys(activity_id,keys) values(aid,$j$[{"answer": 1, "explanation": "The speaker says the boats return before noon."}, {"answer": 0, "explanation": "The speaker asks you to wear your life jacket first."}, {"answer": 2, "explanation": "It started raining heavily, so she stayed at home."}, {"answer": 1, "explanation": "The speaker says the market is closed on Sundays."}, {"answer": 2, "explanation": "The library is opposite the post office."}, {"answer": 3, "explanation": "Adults pay forty rupees and children pay fifteen."}, {"answer": 0, "explanation": "They decided to go out because calm weather was forecast."}, {"answer": 1, "explanation": "The next bus is at half past ten."}, {"answer": 0, "explanation": "The speaker cannot hear and asks the listener to speak louder."}, {"answer": 2, "explanation": "At high tide the water covers the rocks near the shore."}]$j$::jsonb);
  end if;
  if not exists(select 1 from public.activities where title=$t$Speaking pre-test$t$) then
    insert into public.activities(kind,purpose,title,skill,intro,passage,questions,status,sort) values('quiz','pretest',$t$Speaking pre-test$t$,$t$Speaking$t$,$t$Choose the best thing to say, or the right sound, in each situation.$t$,null,$j$[{"type": "mcq", "q": "You meet your teacher at 9 a.m. Which greeting is best?", "options": ["Good night, ma'am.", "Good morning, ma'am.", "What?", "Bye, ma'am."]}, {"type": "mcq", "q": "You did not hear what someone said. What is the polite thing to say?", "options": ["What?", "Say again.", "Could you repeat that, please?", "You are not clear."]}, {"type": "mcq", "q": "Which word is stressed on the first syllable?", "options": ["begin", "about", "hotel", "table"]}, {"type": "tf", "q": "In the word 'knife', the letter k is silent."}, {"type": "mcq", "q": "Which is the most polite way to ask for permission?", "options": ["I am coming in.", "May I come in?", "I come in.", "Let me in."]}, {"type": "mcq", "q": "Which word rhymes with 'sea'?", "options": ["say", "sit", "tree", "sky"]}, {"type": "mcq", "q": "A friend says, 'Thank you for your help.' What is the best reply?", "options": ["You're welcome.", "Yes, I helped you.", "Thank you.", "No."]}, {"type": "tf", "q": "In a yes/no question such as 'Are you ready?', the voice usually rises at the end."}, {"type": "ar", "assertion": "We say 'an umbrella', not 'a umbrella'.", "reason": "The word 'umbrella' begins with a vowel sound."}, {"type": "match", "q": "Match each purpose with the right expression.", "left": ["Greeting", "Apologising", "Thanking", "Leaving"], "right": ["Thanks a lot.", "Hello, how are you?", "See you tomorrow.", "I'm sorry I'm late."]}]$j$::jsonb,'published',11) returning id into aid;
    insert into public.activity_keys(activity_id,keys) values(aid,$j$[{"answer": 1, "explanation": "'Good morning' is the polite greeting before noon."}, {"answer": 2, "explanation": "'Could you ... please?' is a polite request."}, {"answer": 3, "explanation": "We say TA-ble. The other words are stressed on the second syllable."}, {"answer": 0, "explanation": "'Knife' is pronounced 'nife'."}, {"answer": 1, "explanation": "'May I ...?' is the polite form for asking permission."}, {"answer": 2, "explanation": "'Sea' and 'tree' end with the same long 'ee' sound."}, {"answer": 0, "explanation": "'You're welcome' is the usual reply to thanks."}, {"answer": 0, "explanation": "Yes/no questions normally end with rising intonation."}, {"answer": 0, "explanation": "'An' is used before a vowel sound, so the reason explains the assertion."}, {"answer": [1, 3, 0, 2], "explanation": "Each expression is the usual way to do that job in conversation."}]$j$::jsonb);
  end if;
  if not exists(select 1 from public.activities where title=$t$Reading pre-test$t$) then
    insert into public.activities(kind,purpose,title,skill,intro,passage,questions,status,sort) values('reading','pretest',$t$Reading pre-test$t$,$t$Reading$t$,$t$Read the passage, then answer the questions.$t$,$t$<h3>The Morning Catch</h3><p>Before sunrise, the fishermen of a small coastal village push their wooden boats into the sea. They carry nets, drinking water and a little food, because they will be away for six or seven hours. The older fishermen read the wind and the colour of the sky to decide where to go. Younger ones now check the weather forecast on their phones as well.</p><p>By ten o'clock the boats return. Women from the village wait on the beach with baskets. They sort the fish by size, and the best fish are sent to the town market in ice boxes. Small fish are dried in the sun and sold later.</p><p>Life here depends on the sea. When storms come, nobody can fish, and families must live on their savings. That is why the village has started a cooperative. Each family saves a small amount every month, and the money helps everyone during the stormy season.</p>$t$,$j$[{"type": "mcq", "q": "When do the fishermen set out?", "options": ["At ten o'clock", "Before sunrise", "At noon", "After sunset"]}, {"type": "mcq", "q": "How long are they away at sea?", "options": ["Two or three hours", "A whole day", "Six or seven hours", "Ten hours"]}, {"type": "mcq", "q": "How do the older fishermen decide where to go?", "options": ["They read the wind and the sky", "They ask the women", "They use their phones", "They follow other boats"]}, {"type": "tf", "q": "Younger fishermen use their phones to check the weather."}, {"type": "mcq", "q": "What do the women on the beach do?", "options": ["Repair the nets", "Cook the fish", "Push the boats", "Sort the fish by size"]}, {"type": "mcq", "q": "What happens to the best fish?", "options": ["They are dried in the sun", "They are sent to the town market", "They are eaten in the village", "They are thrown back"]}, {"type": "tf", "q": "Small fish are thrown back into the sea."}, {"type": "mcq", "q": "In the passage, a 'cooperative' is", "options": ["a kind of fishing boat", "a group whose members save money and help each other", "a town market", "a weather forecast"]}, {"type": "mcq", "q": "Why did the village start a cooperative?", "options": ["To buy bigger boats", "To sell fish abroad", "To help families during the stormy season", "To build a market"]}, {"type": "ar", "assertion": "Families must live on their savings during storms.", "reason": "Nobody can fish when storms come."}]$j$::jsonb,'published',12) returning id into aid;
    insert into public.activity_keys(activity_id,keys) values(aid,$j$[{"answer": 1, "explanation": "The first sentence says 'Before sunrise'."}, {"answer": 2, "explanation": "They will be away for six or seven hours."}, {"answer": 0, "explanation": "They read the wind and the colour of the sky."}, {"answer": 0, "explanation": "They check the weather forecast on their phones."}, {"answer": 3, "explanation": "They sort the fish by size."}, {"answer": 1, "explanation": "The best fish are sent to the town market in ice boxes."}, {"answer": 1, "explanation": "Small fish are dried in the sun and sold later."}, {"answer": 1, "explanation": "Each family saves money, and the money helps everyone."}, {"answer": 2, "explanation": "The savings help everyone during the stormy season."}, {"answer": 0, "explanation": "Because nobody can fish, there is no income, so families use savings."}]$j$::jsonb);
  end if;
  if not exists(select 1 from public.activities where title=$t$Writing pre-test$t$) then
    insert into public.activities(kind,purpose,title,skill,intro,passage,questions,status,sort) values('quiz','pretest',$t$Writing pre-test$t$,$t$Writing$t$,null,null,$j$[{"type": "mcq", "q": "Which sentence is punctuated correctly?", "options": ["where are you going.", "Where are you going?", "Where are you going", "where are you going?"]}, {"type": "mcq", "q": "Which sentence uses capital letters correctly?", "options": ["ravi lives in chennai.", "Ravi lives in chennai.", "Ravi lives in Chennai.", "ravi lives in Chennai."]}, {"type": "mcq", "q": "Choose the best word: 'It was raining, ___ we stayed indoors.'", "options": ["but", "so", "or", "because"]}, {"type": "tf", "q": "A paragraph usually begins with a topic sentence that gives its main idea."}, {"type": "mcq", "q": "Which word is spelt correctly?", "options": ["beautifull", "beutiful", "beautyful", "beautiful"]}, {"type": "mcq", "q": "Which is the best opening for an email to your professor?", "options": ["Hey Kumar,", "Dear Professor Kumar,", "Hi dude,", "Kumar!"]}, {"type": "mcq", "q": "Which of these is a complete sentence?", "options": ["Because it was late.", "Running along the shore.", "The children played on the beach.", "The boats in the harbour."]}, {"type": "tf", "q": "A formal letter can end with 'Yours sincerely' or 'Yours faithfully'."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["She don't like coffee.", "She not like coffee.", "She doesn't likes coffee.", "She doesn't like coffee."]}, {"type": "match", "q": "Match each part of a letter with its purpose.", "left": ["Salutation", "Body", "Closing", "Signature"], "right": ["gives the main message", "shows who wrote it", "greets the reader", "ends the letter politely"]}]$j$::jsonb,'published',13) returning id into aid;
    insert into public.activity_keys(activity_id,keys) values(aid,$j$[{"answer": 1, "explanation": "A question starts with a capital letter and ends with a question mark."}, {"answer": 2, "explanation": "Names of people and places begin with capital letters."}, {"answer": 1, "explanation": "'So' shows the result of the rain."}, {"answer": 0, "explanation": "The topic sentence tells the reader what the paragraph is about."}, {"answer": 3, "explanation": "The correct spelling is b-e-a-u-t-i-f-u-l."}, {"answer": 1, "explanation": "A formal email begins with 'Dear' and the person's title."}, {"answer": 2, "explanation": "It has a subject (the children) and a complete verb (played)."}, {"answer": 0, "explanation": "These are the standard formal closings."}, {"answer": 3, "explanation": "With 'she' we use 'doesn't' followed by the base verb."}, {"answer": [2, 0, 3, 1], "explanation": "These are the four basic parts of a letter."}]$j$::jsonb);
  end if;
  if not exists(select 1 from public.activities where title=$t$Grammar pre-test$t$) then
    insert into public.activities(kind,purpose,title,skill,intro,passage,questions,status,sort) values('quiz','pretest',$t$Grammar pre-test$t$,$t$Grammar$t$,null,null,$j$[{"type": "mcq", "q": "She ___ to college every day.", "options": ["go", "goes", "going", "gone"]}, {"type": "mcq", "q": "They ___ football yesterday.", "options": ["play", "plays", "played", "playing"]}, {"type": "mcq", "q": "There ___ many boats in the harbour.", "options": ["is", "was", "be", "are"]}, {"type": "tf", "q": "'He don't know the answer' is a correct sentence."}, {"type": "mcq", "q": "I saw ___ elephant at the zoo.", "options": ["a", "an", "the two", "some"]}, {"type": "mcq", "q": "The book is ___ the table.", "options": ["on", "at", "into", "between"]}, {"type": "mcq", "q": "What is the plural of 'child'?", "options": ["childs", "childes", "children", "childrens"]}, {"type": "mcq", "q": "If it rains, we ___ at home.", "options": ["stayed", "will stay", "staying", "had stayed"]}, {"type": "ar", "assertion": "In 'The sun rises in the east', the verb is in the simple present tense.", "reason": "The simple present is used for facts that are always true."}, {"type": "match", "q": "Match each word with its part of speech.", "left": ["quickly", "beautiful", "river", "swim"], "right": ["verb", "adjective", "adverb", "noun"]}]$j$::jsonb,'published',14) returning id into aid;
    insert into public.activity_keys(activity_id,keys) values(aid,$j$[{"answer": 1, "explanation": "With 'she' in the simple present we add -es: goes."}, {"answer": 2, "explanation": "'Yesterday' needs the past tense: played."}, {"answer": 3, "explanation": "'Boats' is plural, so we use 'are'."}, {"answer": 1, "explanation": "The correct form is 'He doesn't know the answer'."}, {"answer": 1, "explanation": "'Elephant' begins with a vowel sound, so we use 'an'."}, {"answer": 0, "explanation": "We use 'on' for something resting on a surface."}, {"answer": 2, "explanation": "'Child' has an irregular plural: children."}, {"answer": 1, "explanation": "A real future condition uses 'if + present, will + verb'."}, {"answer": 0, "explanation": "The sentence states a permanent fact, which is why the simple present is used."}, {"answer": [2, 1, 3, 0], "explanation": "Quickly describes how, beautiful describes a noun, river is a thing, swim is an action."}]$j$::jsonb);
  end if;
  if not exists(select 1 from public.activities where title=$t$Vocabulary pre-test$t$) then
    insert into public.activities(kind,purpose,title,skill,intro,passage,questions,status,sort) values('quiz','pretest',$t$Vocabulary pre-test$t$,$t$Vocabulary$t$,null,null,$j$[{"type": "mcq", "q": "What is the opposite of 'ancient'?", "options": ["old", "modern", "large", "broken"]}, {"type": "mcq", "q": "Which word means the same as 'huge'?", "options": ["tiny", "narrow", "enormous", "quiet"]}, {"type": "mcq", "q": "A person who catches fish for a living is a", "options": ["farmer", "sailor", "fisherman", "diver"]}, {"type": "tf", "q": "A harbour is a safe place where boats and ships are kept."}, {"type": "mcq", "q": "'The sea was calm this morning.' Here 'calm' means", "options": ["quiet and still", "very deep", "cold", "dangerous"]}, {"type": "mcq", "q": "We must ___ water because there has been very little rain.", "options": ["waste", "spill", "pour", "save"]}, {"type": "mcq", "q": "'The test was a piece of cake.' This means the test was", "options": ["very long", "very easy", "about food", "very hard"]}, {"type": "mcq", "q": "Which word means land along the edge of the sea?", "options": ["desert", "valley", "coast", "forest"]}, {"type": "tf", "q": "'Purchase' and 'buy' have nearly the same meaning."}, {"type": "match", "q": "Match each word with its meaning.", "left": ["tide", "net", "lighthouse", "anchor"], "right": ["guides ships with a light", "the rise and fall of the sea", "keeps a boat in one place", "used to catch fish"]}]$j$::jsonb,'published',15) returning id into aid;
    insert into public.activity_keys(activity_id,keys) values(aid,$j$[{"answer": 1, "explanation": "'Ancient' means very old; 'modern' means of the present time."}, {"answer": 2, "explanation": "'Huge' and 'enormous' both mean very large."}, {"answer": 2, "explanation": "A fisherman earns a living by catching fish."}, {"answer": 0, "explanation": "Boats shelter in a harbour."}, {"answer": 0, "explanation": "A calm sea has little wind and few waves."}, {"answer": 3, "explanation": "When there is little rain we need to save water."}, {"answer": 1, "explanation": "'A piece of cake' is an idiom for something very easy."}, {"answer": 2, "explanation": "The coast is the land next to the sea."}, {"answer": 0, "explanation": "'Purchase' is a more formal word for 'buy'."}, {"answer": [1, 3, 0, 2], "explanation": "These are common words about the sea and boats."}]$j$::jsonb);
  end if;
end $seed$;
